#!/usr/bin/env bash
# Создаёт метки, этап «ЛР1: Инициация» и стартовые задачи ЛР 1.
# Безопасно запускать повторно: задачи создаются только если в репозитории их ещё нет.
set -euo pipefail

REPO="${GITHUB_REPOSITORY:?}"
MILESTONE="ЛР1: Инициация"

echo "== Метки =="
mk_label() { gh label create "$1" --color "$2" --description "$3" --force --repo "$REPO" >/dev/null; echo "  $1"; }
mk_label "docs"          "0E8A16" "Документы и тексты"
mk_label "task"          "1D76DB" "Рабочая задача"
mk_label "risk"          "B60205" "Риск проекта"
mk_label "decision"      "5319E7" "Принятое решение (ADR)"
mk_label "priority:high" "D93F0B" "Высокий приоритет"
mk_label "question"      "FBCA04" "Вопрос к команде или заказчику"

echo "== Этап =="
if gh api "repos/$REPO/milestones?state=all" --jq '.[].title' | grep -qxF "$MILESTONE"; then
  echo "  этап уже существует"
else
  gh api "repos/$REPO/milestones" -f title="$MILESTONE" \
    -f description="Устав проекта, стейкхолдеры, подход, доска. Укажите срок сдачи в настройках этапа." >/dev/null
  echo "  создан: $MILESTONE"
fi

echo "== Задачи =="
existing=$(gh issue list --state all --limit 1 --json number --jq 'length' --repo "$REPO")
if [ "$existing" != "0" ]; then
  echo "  в репозитории уже есть задачи, стартовые не создаём"
  exit 0
fi

mk_issue() {
  local title="$1" label="$2" body="$3"
  gh issue create --repo "$REPO" --title "$title" --label "$label" \
    --milestone "$MILESTONE" --body "$body" >/dev/null
  echo "  $title"
}

mk_issue "Заполнить README и добавить участников" "task" \
"Заполнить README (название, вариант, команда, роли), добавить участников и преподавателя в Collaborators, создать доску проекта и вставить ссылку.

## Готово, когда
- [ ] README заполнен, нет шаблонных полей
- [ ] Все участники имеют доступ
- [ ] Ссылка на доску в README"

mk_issue "Составить командный договор" "docs" \
"Заполнить docs/team-agreement.md (шаг 0 задания).

## Готово, когда
- [ ] Заполнены все разделы
- [ ] PR проверил другой участник"

mk_issue "Описать проблему и бизнес-обоснование" "docs" \
"Заполнить docs/business-case.md (шаг 2): проблема, пользователи, решение, ключевой вопрос, альтернативы.

## Готово, когда
- [ ] Минимум 3 источника
- [ ] Рассмотрены минимум 2 альтернативы
- [ ] PR проверил другой участник"

mk_issue "Сформулировать цели SMART и показатели" "docs" \
"Заполнить раздел 2 устава (шаг 3).

## Готово, когда
- [ ] Одна главная цель и 3–4 подцели
- [ ] У каждой цели есть показатель, исходное и целевое значение, срок"

mk_issue "Составить реестр стейкхолдеров и матрицу влияния и интереса" "docs" \
"Заполнить docs/stakeholders.md (шаг 4).

## Готово, когда
- [ ] Минимум 8 стейкхолдеров
- [ ] Матрица построена
- [ ] PR проверил другой участник"

mk_issue "Провести интервью с заказчиком и записать протокол" "docs" \
"Подготовить 8–10 вопросов, провести 30-минутное интервью, записать протокол в docs/meetings/.

## Готово, когда
- [ ] Список вопросов подготовлен заранее
- [ ] Протокол лежит в docs/meetings/"

mk_issue "Составить матрицу RACI" "docs" \
"Заполнить раздел RACI в docs/stakeholders.md.

## Готово, когда
- [ ] Минимум 8 работ
- [ ] В каждой строке ровно одна «A»"

mk_issue "Определить границы, допущения и ограничения" "docs" \
"Заполнить разделы 3 и 4 устава (шаг 5).

## Готово, когда
- [ ] По 5 пунктов «входит» и «не входит»
- [ ] Минимум 4 допущения и ограничения"

mk_issue "Составить бюджет и вехи" "docs" \
"Заполнить разделы 6 и 7 устава (шаг 5).

## Готово, когда
- [ ] 6–8 вех, связанных с ЛР 1–6
- [ ] Бюджет по порядку величины с резервом"

mk_issue "Составить реестр рисков" "risk" \
"Заполнить раздел 9 устава (шаг 5).

## Готово, когда
- [ ] Минимум 7 рисков в формате «Если ..., то ...»
- [ ] Оценка вероятности и влияния, реакция на каждый"

mk_issue "Выбрать модель жизненного цикла и оформить ADR-001" "decision" \
"Заполнить docs/adr/ADR-001-lifecycle.md (шаг 6).

## Готово, когда
- [ ] Заполнена таблица сравнения
- [ ] Решение обосновано и учитывает особенность варианта"

mk_issue "Собрать устав проекта" "docs" \
"Собрать docs/charter.md (шаг 8), убрать пометки TODO и шаблонные поля.

## Готово, когда
- [ ] Заполнены все 11 разделов
- [ ] Есть ссылки на подробные документы
- [ ] PR проверил другой участник"

mk_issue "Подготовить защиту и релиз v0.1-initiation" "task" \
"Подготовить резюме Go/No-Go, презентацию на 5–7 минут, создать релиз v0.1-initiation.

## Готово, когда
- [ ] Презентация готова
- [ ] Релиз создан со ссылкой на устав"

echo "Готово."
